from typing import Literal
from typing_extensions import TypedDict
from langgraph.graph import StateGraph, START, END
class State(TypedDict): request: str; category: str
def classify(s): return {"category": "question" if "?" in s["request"] else "statement"}
def answer(s): return {"request": "질문 처리 완료"}
def store(s): return {"request": "문장 저장 완료"}
def route(s) -> Literal["answer", "store"]: return "answer" if s["category"] == "question" else "store"
b=StateGraph(State); b.add_node("classify",classify); b.add_node("answer",answer); b.add_node("store",store); b.add_edge(START,"classify"); b.add_conditional_edges("classify",route); b.add_edge("answer",END); b.add_edge("store",END)
print(b.compile().invoke({"request":"LangGraph란?","category":""}))

