from langgraph.types import interrupt
def review_node(state):
    approval=interrupt({"question":"게시할까요?","draft":state["draft"]})
    return {"approved":bool(approval)}
print("interrupt는 체크포인터가 활성화된 그래프에서 실행을 중단합니다.")

from typing import Literal
from langgraph.types import Command, interrupt
def approval(state) -> Command[Literal["publish","cancel"]]:
    decision=interrupt({"action":"approve","draft":state["draft"]})
    if decision=="approve": return Command(update={"approved":True},goto="publish")
    return Command(update={"approved":False},goto="cancel")

from langgraph.types import interrupt
def edit_draft(state):
    edited=interrupt({"instruction":"내용을 검토하고 수정하세요.","draft":state["draft"]})
    if not isinstance(edited,str) or not edited.strip(): raise ValueError("수정 내용이 필요합니다.")
    return {"draft":edited.strip(),"reviewed":True}

